SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷八十二", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e4284fc6d71535dbdd9b85d19ca37d8bb9add577/content/books/zizhi-tongjian/vol-283/year-0943/part-05/sources/library/jiuwudaishi-082-943-winter/source.txt", "note": "《旧五代史》卷八十二，段落 jiu-wudaishi-205deb4a7860-p001998；EPUB电子本，纸本及异文待核", "id": "1612e62c-801b-517b-bb9d-a2073e39e947"}, {"title": "资治通鉴·后晋纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e4284fc6d71535dbdd9b85d19ca37d8bb9add577/content/books/zizhi-tongjian/vol-283/year-0943/part-05/sources/library/tongjian-283-943-chu-tax/source.txt", "note": "《资治通鉴》后晋纪四，段落 zizhi-tongjian-a63549944a71-p003370；电子底本待考，分段待核", "id": "c5b333df-c93e-537a-ab94-ce1e313954ff"}, {"title": "资治通鉴·后晋纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e4284fc6d71535dbdd9b85d19ca37d8bb9add577/content/books/zizhi-tongjian/vol-283/year-0943/part-05/sources/library/tongjian-283-943-min-liu-zan/source.txt", "note": "《资治通鉴》后晋纪四，段落 zizhi-tongjian-a63549944a71-p003371；电子底本待考，分段待核", "id": "8f986793-33bf-5758-b6d9-8b3d9a744d1b"}, {"title": "资治通鉴·后晋纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e4284fc6d71535dbdd9b85d19ca37d8bb9add577/content/books/zizhi-tongjian/vol-283/year-0943/part-05/sources/library/tongjian-283-943-year-end/source.txt", "note": "《资治通鉴》后晋纪四，段落 zizhi-tongjian-a63549944a71-p003369；电子底本待考，分段待核", "id": "3a2c6423-177f-5c2b-8f46-de80afe7e8af"}, {"title": "新五代史·卷六十六", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e4284fc6d71535dbdd9b85d19ca37d8