INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "钱弘佐", "aliases": ["錢弘佐"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲许氏。939年条下的王室家属追述提及他，出生年份本句未载。", "biography": null, "status": "draft", "id": "0d604e68-f71f-5263-9e8f-80de6e9feb32"}, {"name": "仰氏（钱弘佐妃）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "仰仁诠的女儿，943年十一月戊子被吴越王钱弘佐纳为妃。个人名字与生卒年未载。", "biography": null, "status": "draft", "id": "f83d4bb2-710e-518f-9dd9-b96f8d0d5b05"}, {"name": "仰仁诠", "aliases": ["仰仁詮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：仰仁诠，受遣牙将。", "biography": null, "status": "draft", "id": "bb229efa-8831-569a-84b2-c48d86bee7a7"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "杨檀", "aliases": ["楊檀", "杨光远", "楊光遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：杨檀，冀州刺史、反对遣归者。", "biography": null, "status": "draft", "id": "54ec3b10-aece-5189-91a8-84a03c5691a3"}, {"name": "景延广", "aliases": ["景延廣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：景延广，原客将、获任者。", "biography": null, "status": "draft", "id": "de8a964e-a028-50ee-8d54-2cbfda481e98"}, {"name": "杨承祚", "aliases": ["楊承祚"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杨光远的儿子。938年五月被任命为左威卫将军，并与石敬瑭的女儿长安公主结婚。", "biography": null, "status": "draft", "id": "2af4e0bd-ddb5-5c72-b4f6-8e3394d31c7d"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "何超", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "金城人，后晋左飞龙使。943年十一月庚子，在杨承祚逃往青州后，被任命暂时主持单州事务。生卒年未载。", "biography": null, "status": "draft", "id": "3277b5a5-c54e-5776-b1ea-fb47c5065b3b"}, {"name": "郭谨", "aliases": ["郭謹"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋侍卫步军都指挥使。943年十一月壬寅奉命率兵驻守郓州。生卒年未载。", "biography": null, "status": "draft", "id": "0269eda3-2432-50c2-990e-2ec09ead5f82"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "蔡行遇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋均州刺史。941年安从进派其弟安从贵率兵迎击蔡行遇，焦继勋截击安从贵并取胜。生卒年未载。", "biography": null, "status": "draft", "id": "c657ba32-a6f0-5c36-b7f0-d962ecf51cc4"}, {"name": "翟进宗", "aliases": ["翟進宗"], "era": "五代十国", "birth_year": null, "death_year": 943, "description": "后晋淄州刺史。943年十二月被杨光远派兵劫往青州；《新五代史》本纪还记其在杨光远反叛中死亡，具体死亡情境与日期本批未核。", "biography": null, "status": "draft", "id": "46c5dbf0-f6e3-5d74-89b9-d05fa9e3467e"}, {"name": "赵延寿", "aliases": ["趙延壽", "延寿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：赵延寿，公主丈夫。", "biography": null, "status": "draft", "id": "bf502cd0-4cbb-52e5-b93a-e30caa907a58"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "周宗", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：周宗。", "biography": null, "status": "draft", "id": "155e76cd-ab0e-5e2a-a791-43d64ebe4669"}, {"name": "宋齐丘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：宋齐丘。", "biography": null, "status": "draft", "id": "313ec6c3-7027-5fef-8b5d-b79d259f9c8a"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "陈觉", "aliases": ["陳覺"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：陈觉，海陵人、参与谈议者。", "biography": null, "status": "draft", "id": "8f8c34eb-c238-596f-a688-8b8332b405a1"}, {"name": "莫彦殊", "aliases": ["莫彥殊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "宁州酋长，943年条下记其率所部温那等十八州归附楚国。史书记这些州未设官府，楚国以立牌和恩威维持羁縻关系。生卒年未载。", "biography": null, "status": "draft", "id": "63eb9733-863d-5e81-b852-657c956ea01e"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "王绪（杜重威判官）", "aliases": ["王緒（杜重威判官）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋顺国节度使杜重威的判官。943年向杜重威提出搜括粮食的办法。与晚唐光州刺史王绪为不同人物，也未证与后晋太常丞王绪同人。生卒年未载。", "biography": null, "status": "draft", "id": "dec91f23-a79e-5ce0-a603-e6bc5fe0e76a"}, {"name": "李沼", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋杜重威的判官。943年受命向民间借粮，所得粮食在次年春出售。生卒年未载。", "biography": null, "status": "draft", "id": "e8511e85-ea3e-503b-9a79-8e35b0c8981e"}, {"name": "马全节", "aliases": ["馬全節"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：马全节，金州防御使、以私财给军并拒战者。", "biography": null, "status": "draft", "id": "bb5608d9-eabe-58ce-8c56-b07e57faadb5"}, {"name": "马希范", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平三年条所见人物：马希范。", "biography": null, "status": "draft", "id": "6c13c07c-57cf-596e-9247-ba0556ac4737"}, {"name": "邓懿文", "aliases": ["鄧懿文"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国营田使，受马希范命登记逃亡民户留下的田地，招募民众耕种缴租。具体任职与行动年月未载。", "biography": null, "status": "draft", "id": "a5089609-5c2a-5e38-90e1-c6c7ab18b843"}, {"name": "周陟", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国孔目官。943年提出在常税之外追加各县贡米的办法，马希范采用。拓跋恒上书请求撤销贡米令、处死周陟，原文未记该请求被执行。生卒年未载。", "biography": null, "status": "draft", "id": "a64f3666-e248-5329-9304-f2633d543ded"}, {"name": "拓跋恒", "aliases": ["元恒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成二年条所见人物：拓跋恒，楚国仆射获任者。", "biography": null, "status": "draft", "id": "a53a8f9a-f7db-5e25-b74c-4b81973658e7"}, {"name": "区弘练", "aliases": ["區弘練"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国客将，拓跋恒被马希范拒绝接见后，向他表达对楚国前景的忧虑。生卒年未载。", "biography": null, "status": "draft", "id": "95a2858b-8a47-5c4e-a6b6-770898eedac4"}, {"name": "王延羲", "aliases": ["王曦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国宗室，王继鹏的叔父，曾任左仆射、同平章事。939年被政变军队拥立，自称威武节度使、闽国王，更名王曦，改元永隆。生卒年暂未核实。", "biography": null, "status": "draft", "id": "e706d6ae-56f4-5e44-9d24-f3060ae87cbb"}, {"name": "刘赞（闽御史中丞）", "aliases": ["劉贊（閩御史中丞）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国御史中丞。王延羲因嫁女时有朝士未道贺，准备杖责未弹劾他们的刘赞。郑元弼劝谏后，刘赞被释放；《资治通鉴》还记他最终忧郁而死，确切年月未载。与前蜀嘉州司马刘赞及后唐秦王傅刘赞分别建档。", "biography": null, "status": "draft", "id": "c54e7689-bde1-5f7f-878e-105eb5a6c3a6"}, {"name": "郑元弼", "aliases": ["鄭元弼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国礼部员外郎。939年奉王继恭的表章，随卢损前往后晋进贡。生卒年未载。", "biography": null, "status": "draft", "id": "a656f099-5f42-574b-bfa0-daa89cb73913"}]'::jsonb)
